"""Compile developer-tools/ui_tokens.json into Ren'Py theme files and 9-slice UI surfaces."""

import json
from pathlib import Path
from generate_ui_surfaces import generate_from_tokens

TOOLS_DIR = Path(__file__).resolve().parent
ROOT_DIR = TOOLS_DIR.parent
TOKENS_PATH = TOOLS_DIR / "ui_tokens.json"
THEME_DIR = ROOT_DIR / "game" / "30_screens" / "theme"


def compile_gui_00_tokens(tokens: dict) -> str:
    colors = tokens["colors"]
    typography = tokens["typography"]
    spacing = tokens["spacing"]
    badges = colors["badges"]

    lines = [
        "# AUTO-GENERATED by developer-tools/compile_ui_tokens.py from ui_tokens.json.",
        "# Do not edit manually; update ui_tokens.json and re-run compile_ui_tokens.py.",
        "",
        "init offset = -2",
        "",
        f'define gui.gold_hover = "{colors["gold_hover"]}"',
        f'define gui.choice_idle_color = "{colors["choice_idle_color"]}"',
        f'define gui.bg_dark = "{colors["bg_dark"]}"',
        "",
        f'define gui.hint_text_size = {typography["hint_text_size"]}',
        f'define gui.pill_text_size = {typography["pill_text_size"]}',
        "",
        f'define gui.choice_btn_width = {spacing["choice_btn_width"]}',
        f'define gui.choice_btn_pad = ({spacing["choice_btn_pad"][0]}, {spacing["choice_btn_pad"][1]})',
        f'define gui.pill_pad = ({spacing["pill_pad"][0]}, {spacing["pill_pad"][1]})',
        f'define gui.window_width = {spacing["window_width"]}',
        f'define gui.window_pad = ({spacing["window_pad"][0]}, {spacing["window_pad"][1]})',
        f'define gui.namebox_pad = ({spacing["namebox_pad"][0]}, {spacing["namebox_pad"][1]})',
        "",
        "define gui.badge_colors = {",
    ]
    for k, v in badges.items():
        lines.append(f'    "{k}": "{v}",')
    lines.extend([
        "}",
        "",
        "# Player QoL & accessibility defaults (Dispatch-inspired)",
        "default persistent.ui_text_scale = 1.0",
        "default persistent.ui_reduce_blur = False",
        "default persistent.ui_high_contrast = False",
        "",
    ])
    return "\n".join(lines)


def compile_gui_01_colors_fonts(tokens: dict) -> str:
    c = tokens["colors"]
    t = tokens["typography"]
    lines = [
        "# AUTO-GENERATED by developer-tools/compile_ui_tokens.py from ui_tokens.json.",
        "# Global palette and typography.",
        "",
        "init offset = -1",
        "",
        f'define gui.accent_color = "{c["accent_color"]}"',
        f'define gui.accent_secondary = "{c["accent_secondary"]}"',
        f'define gui.accent_highlight = "{c["accent_highlight"]}"',
        f'define gui.idle_color = "{c["idle_color"]}"',
        f'define gui.idle_small_color = "{c["idle_small_color"]}"',
        f'define gui.hover_color = "{c["hover_color"]}"',
        f'define gui.selected_color = "{c["selected_color"]}"',
        f'define gui.insensitive_color = "{c["insensitive_color"]}"',
        f'define gui.muted_color = "{c["muted_color"]}"',
        f'define gui.hover_muted_color = "{c["hover_muted_color"]}"',
        f'define gui.text_color = "{c["text_color"]}"',
        f'define gui.text_secondary = "{c["text_secondary"]}"',
        f'define gui.text_muted = "{c["text_muted"]}"',
        f'define gui.interface_text_color = "{c["interface_text_color"]}"',
        "",
        f'define gui.text_font = "{t["text_font"]}"',
        f'define gui.name_text_font = "{t["name_text_font"]}"',
        f'define gui.interface_text_font = "{t["interface_text_font"]}"',
        f'define gui.text_size = {t["text_size"]}',
        f'define gui.name_text_size = {t["name_text_size"]}',
        f'define gui.interface_text_size = {t["interface_text_size"]}',
        f'define gui.label_text_size = {t["label_text_size"]}',
        f'define gui.notify_text_size = {t["notify_text_size"]}',
        f'define gui.title_text_size = {t["title_text_size"]}',
        "",
        f'define gui.language = "{t["language"]}"',
        "define gui.about = None",
        "",
    ]
    return "\n".join(lines)


def main() -> None:
    tokens = json.loads(TOKENS_PATH.read_text(encoding="utf-8"))
    THEME_DIR.mkdir(parents=True, exist_ok=True)
    (THEME_DIR / "gui_00_tokens.rpy").write_text(compile_gui_00_tokens(tokens), encoding="utf-8")
    (THEME_DIR / "gui_01_colors_fonts.rpy").write_text(compile_gui_01_colors_fonts(tokens), encoding="utf-8")
    generate_from_tokens(TOKENS_PATH)
    print(f"Compiled UI tokens -> {THEME_DIR / 'gui_00_tokens.rpy'} & {THEME_DIR / 'gui_01_colors_fonts.rpy'}")


if __name__ == "__main__":
    main()
